def contacts_from_demos(apps, schema_editor):
    """The people who already asked for demos, oldest first (their newest details win)."""
    TrialRequest = apps.get_model('orchestrator', 'TrialRequest')
    Contact = apps.get_model('orchestrator', 'Contact')
    for trial in TrialRequest.objects.select_related('project').order_by('created_at'):
        if trial.project is None:
            continue
        contact, _ = Contact.objects.get_or_create(
            owner_id=trial.project.owner_id, email=trial.email.lower(),
            defaults={'name': trial.name, 'first_project_id': trial.project_id})
        for field in ('name', 'company', 'job_title', 'phone', 'country'):
            if getattr(trial, field):
                setattr(contact, field, getattr(trial, field))
        contact.last_request_at = trial.created_at
        contact.save()
        Contact.objects.filter(pk=contact.pk).update(created_at=min(contact.created_at, trial.created_at))
        TrialRequest.objects.filter(pk=trial.pk).update(contact=contact)


